from __future__ import absolute_import
from robot.api import logger as robot_logger
from ute_common_store import Store

from hran_file_operations.parsers.scfc.base import UniversalScfcParser
from hran_file_operations.parsers.scfc.lte import LteScfcParser
from hran_file_operations.parsers.scfc.sbts import SbtsScfcParser
from hran_file_operations.parsers.scfc.swbt import SwbtScfcParser


class ScfcParser(object):
    """
    | **Author:** damian.skrzypczak@nokia.com
    | **Maintainer:** marcin.wieliczko@nokia.com
    | **Released with version:** ---

    | **Full description:**
    | High-level interface for scfc parser for each technology.
    | All technologies and their parsing classes
    | are mapped in "parsers" dictionary.

    """

    parsers = {"WCDMA": SwbtScfcParser,
               "SBTS": SbtsScfcParser,
               "LTE": LteScfcParser,
               "UNIVERSAL": UniversalScfcParser}

    def __init__(self):
        """
        Create a new SCFCParser obj which can handle multiple parsers at once.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---
        """
        self._store = Store()
        self.logger = robot_logger
        self.technology = None

    def setup_scfc_parser(self, scfc, parser_technology, from_string=False,
                          alias="default", logger=None):
        """
        Keyword for setting scfc parser.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Setup scfc parser for given scfc file path and technology
        | for more than one scfc parser working at the time,
        | use "alias" system.

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | scfc               | Yes    | SCFC name/path or file object or      |
        |                    |        | a URL using the HTTP or FTP protocol  |
        +--------------------+--------+---------------------------------------+
        | parser_technology  | Yes    | Parser supported technology -         |
        |                    |        | available: WCDMA/SBTS/LTE/UNIVERSAL   |
        +--------------------+--------+---------------------------------------+
        | from_string        | No     | If given, "scfc" parameter will be    |
        |                    |        | threaten as string                    |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | Optional alias for chosen parser,     |
        |                    |        | useful when more than one             |
        |                    |        | parser is used                        |
        +--------------------+--------+---------------------------------------+
        | logger             | No     | Optional logger, default is           |
        |                    |        | robot.api.logger                      |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           Setup scfc parser  /home/some/path/lte_scfc.xml  LTE

        | **Return values:**
        | True when PASS
        | False when FAIL
        """
        self.logger = logger or self.logger
        try:
            chosen_parser = self.parsers[parser_technology]
            parser = chosen_parser(scfc, from_string, logger=self.logger)
            self._store.add(parser, alias=alias)
            self.technology = parser_technology
            return True
        except KeyError:
            self.logger.error(
                'Could not find parser for technology "{}".'.format(
                    self.technology) +
                'Available technologies: {}'.format(", ".join(self.parsers)))
            return False
        except IOError:
            self.logger.error(
                ("SCF Parser did not start because "
                 "there is no appropriate SCF under {}").format(scfc)
            )
            return False
        except Exception as e:
            self.logger.error(
                "{} Parser failed with error {}".format(parser_technology, e))
            return False

    def teardown_scfc_parser(self, alias="default"):
        """
        Keyword for removing scfc parser.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Shutdown scfc parser

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | alias              | No     | If given, parser under                |
        |                    |        | alias will be used                    |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           Teardown scfc parser
        """
        self._store.remove(alias)

    def save_scfc(self, dest, alias="default"):
        """
        Keyword for saving scfc file, required to save
        changes made on managedObject dictionaries.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | dest               | Yes    | Destination path or file object or    |
        |                    |        | a URL using the HTTP or FTP protocol  |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+

        | **Return values:**
        | True when PASS
        | False when FAIL
        """
        try:
            self._store.get(alias).save_scfc(dest)
            return True
        except Exception as e:
            self.logger.error("Error during scfc saving: {}".format(e))
            return False

    def get_parameters_count(self, alias="default"):
        """
        Get number of parameters in scfc file

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** 3.2.0

        | **Full description:**
        | Get number of parameters in scfc file given in setup
        | parameter in scfc file is represented by <p> tag

        **Input Parameters:**

        +----------------+------+-------------------------------------------+
        | Parameters     | Man. | Description                               |
        +================+=========+========================================+
        | alias          | No   | If given, parser under alias will be used |
        +----------------+------+-------------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${parameters_count}=  Get parameters count
        """
        return len(self.get_parameters(alias))

    def get_parameters(self, alias="default"):
        """
        Get all parameters in scfc file

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** 3.2.0

        | **Full description:**
        | Get all parameters in scfc file given in setup
        | parameter in scfc file is represented by <p> tag

        **Input Parameters:**

        +----------------+------+-------------------------------------------+
        | Parameters     | Man. | Description                               |
        +================+=========+========================================+
        | alias          | No   | If given, parser under alias will be used |
        +----------------+------+-------------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${parameters_count}=  Get parameters count
        """
        return self._store.get(alias).parameters

    def get_managed_objects(self, class_name, alias="default", full_distname=False):
        """
        Keyword for getting all managed objects with given class.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Keyword for getting managed objects
        | that have class attribute compatible with given one
        | excluding prefixes like "com.nokia.x.x"

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | class_name         | Yes    | managed objects class name,           |
        |                    |        | prefixes like "com.nokia.x.x:"        |
        |                    |        | are not allowed                       |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | If given, parser under                |
        |                    |        | alias will be used                    |
        +--------------------+--------+---------------------------------------+
        | full_distname      | No     | If True, entire distname              |
        |                    |        | will be returned                      |
        +--------------------+--------+---------------------------------------+
        **Example:**

        .. code-block:: robotframework

           ${managed_objects}=  Get managed objects  class_name=RMOD

        | **Return values:**
        | List of managed objects with given class
        | where single managed object is dict with
        | parameters from scfc {ParameterName: ParameterValue}
        """
        return self._store.get(alias).get_managed_objects(class_name, full_distname)

    def get_cells(self, technology="", alias="default"):
        """
        Keyword getter for cells.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Get cells objects in scfc split into technologies
        | when specific technology is given,
        | instead of dictionary of technologies,
        | list of cells dictionaries will be return

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | technology         | No     | If given, return cells list for       |
        |                    |        | specific technology -                 |
        |                    |        | available: WCDMA/SBTS/LTE             |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${cells}=  Get cells

        **Example with technology:**

        .. code-block:: robotframework

           ${cells}=  Get cells  technology=LTE

        | **Return values:**
        | Dict [key: Technology -> value: List of cells]
        | where single Cell is dict with
        | parameters from scfc {ParameterName: ParameterValue}
        """
        if technology:
            return self.get_cells()[technology]
        return self._store.get(alias).cells

    def get_iot_cells(self, technology="", alias="default"):
        """
        Keyword getter for IOT cells.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Get only IOT cells objects in scfc
        | when specific technology is given,
        | instead of dictionary of technologies,
        | list of cells dictionaries will be return

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | technology         | No     | If given, return IoT cells list for   |
        |                    |        | specific technology - available:      |
        |                    |        | WCDMA/SBTS/LTE                        |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${iot_cells}=  Get iot cells

        **Example with technology:**

        .. code-block:: robotframework

           ${iot_cells}=  Get iot cells  technology=LTE

        | **Return values:**
        | Dict [key: Technology -> value: List of IoT cells]
        | where single Cell is dict with
        | parameters from scfc {ParameterName: ParameterValue}
        """
        if technology:
            return self.get_cells()[technology]
        return self._store.get(alias).iot_cells

    def get_cells_count(self, technology="", alias="default"):
        """
        Keyword for getting number of cells found.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Keyword for getting count of cells
        | count of all cells is returned when not technology is specified

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | technology         | No     | If given, return count for specific   |
        |                    |        | technology - available:               |
        |                    |        | WCDMA/SBTS/LTE                        |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${cells_count}=  Get cells count

        **Example with technology:**

        .. code-block:: robotframework

           ${cells_count}=  Get cells count  technology=LTE

        | **Return values:**
        | Number of cells found
        | if not technology specified, all cells count is returned
        """
        if technology:
            return len(self.get_cells(technology, alias))
        return len(sum(list(self._store.get(alias).cells.values()), []))

    def get_iot_cells_count(self, technology="", alias="default"):
        """
        Keyword for getting number of IoT cells found.

        | **Author:** gabriel.stanculescu@nokia.com
        | **Maintainer:** gabriel.stanculescu@nokia.com
        | **Released with version:** ---

        | **Full description:**
        | Keyword for getting count of IOT cells
        | count of all cells is returned when not technology is specified

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | technology         | No     | If given, return count for specific   |
        |                    |        | technology - available:               |
        |                    |        | WCDMA/SBTS/LTE                        |
        +--------------------+--------+---------------------------------------+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+


        **Example:**

        .. code-block:: robotframework

           ${iot_cells_count}=  Get iot cells count

        **Example with technology:**

        .. code-block:: robotframework

           ${iot_cells_count}=  Get iot cells count  technology=LTE

        | **Return values:**
        | Number of IOT cells found
        """
        if technology:
            return len(self.get_iot_cells(technology, alias))
        return len(sum(list(self._store.get(alias).iot_cells.values()), []))

