    def get_radios_count(self, alias="default"):
        """
        Keyword for getting radio module number.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${rmod_count}=  Get radio modules count

        | **Return values:**
        | Number of radio modules found
        """
        return len(self.get_radios(alias))

    def get_radios_ips(self, alias="default"):
        """
        [WCDMA ONLY] Keyword for getting
        ip addresses of connected radio modules.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | alias              | No     | If given,                             |
        |                    |        | parser under alias will be used       |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${rmods_ips}=  Get radios ips

        | **Return values:**
        | List of strings: ip address of connected radio modules
        """
        if self._current_parser_in([SwbtScfcParser], alias):
            radios_ips = [radio.get("ip") for radio in
                          self._store.get(alias).rmods]
            if not radios_ips:
                self.logger.warn(
                    "No radios or there's no ips mapped to found ones")
            return radios_ips

