    def find_all_modules_in_scf(self, alias="default"):
        """
        [WCDMA ONLY] Keyword for getting units decelerated in SCFC file.

        | **Author:** damian.skrzypczak@nokia.com
        | **Maintainer:** marcin.wieliczko@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | alias              | No     | If given, parser                      |
        |                    |        | under alias will be used              |
        +--------------------+--------+---------------------------------------+

        **Example:**

        .. code-block:: robotframework

           ${units}=  Find all modules in scf

        | **Return values:**
        | Declared units in SCFC file.
        | Returns dictionary {'unitName': 'variant'} and BTS ID
        """
        if self._current_parser_in([SwbtScfcParser], alias):
            return self._store.get(alias).units

    def _current_parser_in(self, parsers, alias):
        verdict = self._store.get(alias).__class__ in parsers
        if verdict:
            self.logger.warn(
                "This method is not supported by {} technology".format(
                    self.technology))
        return verdict
